-- Source: Egypt Data Portal (opendataforafrica.org/Egypt) (150 rows)
-- Generated by gen_mart_models.py

-- DEDUP (2026-08-18 verification): 100% of the 98-row surplus is 2 groups of 50
-- identical site-navigation-boilerplate rows ("Sign Up" login link, "Data
-- Catalog" nav link) that the portal crawler logged once per crawled subpage --
-- not repeated real indicator data. Confirm query showed a SINGLE load run
-- (1 distinct _SOURCE_RUN_ID); live: 150 rows / 52 distinct -- single-load
-- duplication, exact dups carry no information.
with source as (
    select * from {{ source('ripple_raw', 'INTL_EG_CAPMAS') }}
    qualify row_number() over (
        partition by INDICATOR_NAME, CATEGORY, "YEAR", "VALUE", UNIT, SOURCE, COUNTRY
        order by _INGESTED_AT) = 1
)

select
    INDICATOR_NAME as indicator_name,
    CATEGORY as category,
    try_to_number("YEAR") as year,
    try_to_double("VALUE") as value,
    UNIT as unit,
    SOURCE as source,
    COUNTRY as country
from source
